import java.util.*;

class Solution {
    public int maxChunksToSorted(int[] arr) {
        Deque<Integer> stack = new ArrayDeque<>();
        for (int value : arr) {
            if (stack.isEmpty() || stack.peek() <= value) {
                stack.push(value);
                continue;
            }

            int mergedMax = stack.pop();
            while (!stack.isEmpty() && stack.peek() > value) {
                mergedMax = Math.max(mergedMax, stack.pop());
            }
            stack.push(mergedMax);
        }
        return stack.size();
    }
}

class Solution {
    public int maxChunksToSorted(int[] arr) {
        int n = arr.length;
        int[] suffixMin = new int[n + 1];
        suffixMin[n] = Integer.MAX_VALUE;
        for (int i = n - 1; i >= 0; i--) {
            suffixMin[i] = Math.min(arr[i], suffixMin[i + 1]);
        }

        int chunks = 0;
        int prefixMax = Integer.MIN_VALUE;
        for (int i = 0; i < n; i++) {
            prefixMax = Math.max(prefixMax, arr[i]);
            if (prefixMax <= suffixMin[i + 1]) {
                chunks++;
            }
        }
        return chunks;
    }
}

import java.util.*;

class Solution {
    public int maxChunksToSorted(int[] arr) {
        int[] sorted = arr.clone();
        Arrays.sort(sorted);

        long originalSum = 0;
        long sortedSum = 0;
        int chunks = 0;
        for (int i = 0; i < arr.length; i++) {
            originalSum += arr[i];
            sortedSum += sorted[i];
            if (originalSum == sortedSum) {
                chunks++;
            }
        }
        return chunks;
    }
}

import java.util.*;

class Solution {
    public int maxChunksToSorted(int[] arr) {
        int[] sorted = arr.clone();
        Arrays.sort(sorted);

        Map<Integer, Integer> balance = new HashMap<>();
        int nonZero = 0;
        int chunks = 0;
        for (int i = 0; i < arr.length; i++) {
            nonZero = adjust(balance, arr[i], 1, nonZero);
            nonZero = adjust(balance, sorted[i], -1, nonZero);
            if (nonZero == 0) {
                chunks++;
            }
        }
        return chunks;
    }

    private int adjust(Map<Integer, Integer> balance, int value, int delta, int nonZero) {
        int before = balance.getOrDefault(value, 0);
        int after = before + delta;
        if (before == 0 && after != 0) {
            nonZero++;
        } else if (before != 0 && after == 0) {
            nonZero--;
        }

        if (after == 0) {
            balance.remove(value);
        } else {
            balance.put(value, after);
        }
        return nonZero;
    }
}

import java.util.*;

class Solution {
    public int maxChunksToSorted(int[] arr) {
        int[] sorted = arr.clone();
        Arrays.sort(sorted);

        Map<Integer, ArrayDeque<Integer>> targetPositions = new HashMap<>();
        for (int i = 0; i < sorted.length; i++) {
            targetPositions.computeIfAbsent(sorted[i], key -> new ArrayDeque<>()).addLast(i);
        }

        int maxTarget = -1;
        int chunks = 0;
        for (int i = 0; i < arr.length; i++) {
            int target = targetPositions.get(arr[i]).removeFirst();
            maxTarget = Math.max(maxTarget, target);
            if (maxTarget == i) {
                chunks++;
            }
        }
        return chunks;
    }
}
